#[derive(Debug, PartialEq)]
enum Color {
    None,
    White,
    Red,
    Green,
    Blue,
    Cyan,
    Yellow,
    Grey,
    Bright,
    BrightRed,
    BrightGreen,
    LightGrey,
    BrightWhite,
    BrightBlue,
    BrightCyan,
    BrightMagenta,
    BrightYellow,
    Magenta,
}

fn color_to_string(color: Color) -> &'static str {
    match color {
        Color::Red => "\x1b[31m",
        Color::Green => "\x1b[32m",
        Color::Yellow => "\x1b[33m",
        Color::Blue => "\x1b[34m",
        Color::Magenta => "\x1b[35m",
        Color::Cyan => "\x1b[36m",
        Color::White => "\x1b[37m",
        Color::BrightRed => "\x1b[91m",
        Color::BrightGreen => "\x1b[92m",
        Color::BrightYellow => "\x1b[93m",
        Color::BrightBlue => "\x1b[94m",
        Color::BrightMagenta => "\x1b[95m",
        Color::BrightCyan => "\x1b[96m",
        Color::BrightWhite => "\x1b[97m",
        Color::Grey => "\x1b[90m",
        Color::LightGrey => "\x1b[37m",
        _ => "\x1b[0m",
    }
}

