#[derive(Debug, Copy, Clone, PartialEq)]
enum AssertType {
    Warn,
    Check,
    Require,
    WarnFalse,
    CheckFalse,
    RequireFalse,
    Throws,
    ThrowsAs,
    ThrowsWith,
    NoThrow,
    WarnUnary,
    CheckUnary,
    RequireUnary,
    WarnUnaryFalse,
    CheckUnaryFalse,
    RequireUnaryFalse,
}

impl AssertType {
    fn is_warn(&self) -> bool {
        matches!(self, AssertType::Warn | AssertType::WarnFalse | AssertType::Throws)
    }

    fn is_check(&self) -> bool {
        matches!(self, AssertType::Check | AssertType::CheckFalse | AssertType::ThrowsAs)
    }

    fn is_require(&self) -> bool {
        matches!(self, AssertType::Require | AssertType::RequireFalse | AssertType::ThrowsWith)
    }
}

#[derive(Debug)]
enum TestCaseFailureReason {
    None,
    AssertFailure,
    Exception,
    Crash,
    TooManyFailedAsserts,
}

#[derive(Debug, PartialEq)]
struct TestCaseData<'a> {
    file: &'a str,
    line: u32,
    name: &'a str,
    test_suite: &'a str,
    description: Option<&'a str>,
    should_fail: bool,
    may_fail: bool,
    expected_failures: u32,
    timeout: Duration,
}

#[derive(Debug, Default)]
struct TestRunStats {
    num_test_cases: u32,
    num_test_cases_passing_filters: u32,
    num_test_cases_failed: u32,
}

#[derive(Debug)]
struct CurrentTestCaseStats {
    seconds_duration: Duration,
    failure_flags: TestCaseFailureReason,
}

impl Default for CurrentTestCaseStats {
    fn default() -> Self {
        Self {
            seconds_duration: Duration::new(0, 0),
            failure_flags: TestCaseFailureReason::None,
        }
    }
}

// =================================================================================================
// Context options and state
// =================================================================================================

#[derive(Default)]
struct ContextOptions {
    case_sensitive: bool,
    success: bool,
    duration: bool,
    no_throw: bool,
    no_colors: bool,
    force_colors: bool,
    no_debug_output: bool,
}

#[derive(Default)]
struct ContextState<'a> {
    options: ContextOptions,
    test_cases: Vec<TestCaseData<'a>>,
    current_test: Option<TestCaseData<'a>>,
    current_test_stats: CurrentTestCaseStats,
    run_stats: TestRunStats,
}

impl<'a> ContextState<'a> {
    fn new() -> Self {
        Self {
            options: ContextOptions::default(),
            test_cases: vec![],
            current_test: None,
            current_test_stats: CurrentTestCaseStats::default(),
            run_stats: TestRunStats {
                num_test_cases: 0,
                num_test_cases_passing_filters: 0,
                num_test_cases_failed: 0,
            },
        }
    }

    fn reset_current_test_stats(&mut self) {
        self.current_test_stats = CurrentTestCaseStats::default();
    }
}

